Hier ist eine C++-Funktion, die einen Markdown-formatierten Text als Eingabe entgegennimmt und einen HTML-formatierten Text als Rückgabe liefert:

```cpp
#include <iostream>
#include <string>
#include <sstream>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    // Regular expressions for Markdown syntax
    static const std::regex heading_regex{"^(#{1,6})\\s+(.+)\\s*(#*)?$"};
    static const std::regex bold_regex{"\\*([^*]*)\\*"};
    static const std::regex italic_regex{"([^_]*_)(.+)_([^_]*)"};
    static const std::regex link_regex{"\\[([^\\]]*)\\]\\(([^\\s]*)\\)"};
    static const std::regex image_regex{"!\\[([^\\]]*)\\]\\(([^\\s]*)\\)"};
    static const std::regex unordered_list_regex{"^\\s*-\\s+(.+)"};
    static const std::regex ordered_list_regex{"^\\s\\d+\\.\\s+(.+)"};
    static const std::regex code_block_regex{"^\\s`(.+)`\\s"};

    std::stringstream html_stream;

    // Replace headings with HTML tags
    for (std::smatch match; std::regex_search(markdown, match, heading_regex); markdown = match.suffix()) {
        std::string level = match[1].str();
        std::string text = match[2].str();
        std::string underline = match[3].str();

        std::string html_tag;
        for (int I = 0; I < level.length(); i++) {
            html_tag += "<h" + std::to_string(level.length() - i) + ">";
        }
        html_tag += text;
        for (int I = 0; I < underline.length(); i++) {
            html_tag += "</h" + std::to_string(level.length() - i) + ">";
        }

        html_stream << html_tag << std::endl;
    }

    // Replace bold text with HTML tags
    markdown = std::regex_replace(markdown, bold_regex, "<strong>$1</strong>");

    // Replace italic text with HTML tags
    markdown = std::regex_replace(markdown, italic_regex, "<em>$1</em>");

    // Replace links with HTML tags
    markdown = std::regex_replace(markdown, link_regex, "<a href=\"$2\">$1</a>");

    // Replace images with HTML tags
    markdown = std::regex_replace(markdown, image_regex, "<img src=\"$2\" alt=\"$1\">");

    // Replace unordered lists with HTML tags
    std::string list_item;
    for (std::smatch match; std::regex_search(markdown, match, unordered_list_regex); markdown = match.suffix()) {
        list_item = "<li>" + match[1].str() + "</li>";
        html_stream << "<ul>" << list_item << "</ul>";
    }

    // Replace ordered lists with HTML tags
    int list_counter = 1;
    for (std::smatch match; std::regex_search(markdown, match, ordered_list_regex); markdown = match.suffix()) {
        std::string text = match[1].str();
        list_item = "<li>" + text + "</li>";
        html_stream << "<ol start=\"" << list_counter << "\">" << list_item << "</ol>";
        list_counter++;
    }

    // Replace code blocks with HTML tags
    for (std::smatch match; std::regex_search(markdown, match, code_block_regex); markdown = match.suffix()) {
        std::string text = match[1].str();
        html_stream << "<pre><code>" << text << "</code></pre>";
    }

    // Join HTML stream into a single string
    std::string html = html_stream.str();

    return html;
}

int main() {
    std::string markdown = "## Heading\n"
                           "Text with **bold** and *italic* parts.\n"
                           "[Link](https://example.com) and an ! [Image](https://example.com/image.jpg).\n"
                           "- Item 1\n"
                           "  - Nested item\n"
                           "1. Item 2\n"
                           "   1. Nested item 2\n"
                           "   2. Nested item 3\n"
                           "```\n"
                           "Code block\n"
                           "```\n";

    std::string html = markdownToHtml(markdown);

