Um ein First-Person-Controller-Skript in GDScript für Godot Engine 3.x zu schreiben und es auf einen KinematicBody-Knoten anzuwenden, können Sie die folgenden Schritte befolgen:

1. Erstellen Sie eine neue Szene und fügen Sie einen KinematicBody-Knoten hinzu, den Sie als Controller-Knoten verwenden werden.
2. Öffnen Sie das Controller-Skript des KinematicBody-Knotens und fügen Sie das folgende GDScript hinzu:

```gdscript
# First-Person-Controller Script

export var speed := 10.0
export var mouse_sensitivity := 0.3

var velocity := Vector3.ZERO
var rotation := Vector3.ZERO
var camera_transform := Transform()

func _ready():
    # Set the initial camera transform
    camera_transform = $Camera.global_transform

func _unhandled_input(event):
    if event.is_action_pressed("move_forward"):
        velocity.z += 1
    if event.is_action_pressed("move_backward"):
        velocity.z -= 1
    if event.is_action_pressed("move_left"):
        velocity.x -= 1
    if event.is_action_pressed("move_right"):
        velocity.x += 1

    if event.is_action_released("move_forward") or event.is_action_released("move_backward"):
        velocity.z = 0
    if event.is_action_released("move_left") or event.is_action_released("move_right"):
        velocity.x = 0

    if event.is_action_pressed("turn_left"):
        rotation.y -= mouse_sensitivity
    if event.is_action_pressed("turn_right"):
        rotation.y += mouse_sensitivity

    if event.is_action_released("turn_left") or event.is_action_released("turn_right"):
        rotation.y = 0

func _physics_process(delta):
    # Apply movement and rotation
    velocity = velocity.normalized() * speed
    rotation.y = rotation.y.clamped(math.pi / 4)  # Limit rotation to +/- 45 degrees
    move_and_slide(velocity, Vector3.UP)
    $Camera.rotate_object_local(Vector3.UP, rotation.y)
```

